using System;
using ObjCRuntime;
using Foundation;
using CoreFoundation;

namespace Net.Agora.Chat.iOS {

	// Hand-written against the real AgoraChat.xcframework headers from Agora_Chat_iOS 1.4.0
	// (io.agora.rtc:chat-sdk's iOS counterpart) rather than generated by Objective Sharpie — same
	// reasoning as the RTC and Signaling bindings' ApiDefinition.cs: sharpie's bundled clang
	// cannot parse SDKs from current Xcode.
	//
	// Scoped to what the thin Net.Agora.Chat client needs — initialise the SDK, log in and out,
	// renew the token, list conversations, send and receive text messages, and the delegate
	// callbacks for those — not the SDK's full surface. AgoraChat ships 67 public headers: groups,
	// chat rooms, threads, presence, contacts, reactions, translation, push and multi-device are
	// all deliberately unbound. Extend here as more is needed; the pattern for a new manager is
	// AgoraChatManager below.
	//
	// Enums live in StructsAndEnums.cs; the block delegate types stay here — the binding generator
	// emits a trampoline for a delegate declared in the api definition file itself, and duplicates
	// it if the same type is declared again in the core source file.

	// The completion block on -loginWithUsername:token:completion: — AgoraChatClient.h. aError is
	// nil on success.
	public delegate void AgoraChatLoginHandler (string username, [NullAllowed] AgoraChatError error);

	// The completion block on -logout:completion: and -renewToken:completion: — AgoraChatClient.h.
	public delegate void AgoraChatCompletionHandler ([NullAllowed] AgoraChatError error);

	// The progress block on -sendMessage:progress:completion: — IAgoraChatManager.h. The value is
	// attachment upload progress in [0,100]; a text message never reports any.
	public delegate void AgoraChatProgressHandler (int progress);

	// The completion block on -sendMessage:progress:completion: — IAgoraChatManager.h. On success
	// the message is the same instance that was passed in, with its status and server-assigned
	// messageId updated.
	public delegate void AgoraChatMessageHandler ([NullAllowed] AgoraChatMessage message, [NullAllowed] AgoraChatError error);

	// AgoraChatError — AgoraChatError.h. Not an NSError subclass, unlike Signaling's
	// AgoraRtmErrorInfo. Code is the SDK's AgoraChatErrorCode — ~90 values; carried as its raw
	// NSInteger rather than binding an enum, matching how Signaling handles AgoraRtmErrorCode.
	[BaseType (typeof (NSObject))]
	public interface AgoraChatError {
		[Export ("code")]
		nint Code { get; set; }

		[Export ("errorDescription")]
		string ErrorDescription { get; set; }
	}

	// AgoraChatOptions — AgoraChatOptions.h. Two factory methods, because Agora migrated Chat from
	// an Easemob "app key" to an Agora App ID and both still work; an app uses whichever its
	// project was provisioned with. The rest of the class is ~30 behaviour switches left unbound
	// apart from the three a first-run app actually sets.
	[BaseType (typeof (NSObject))]
	[DisableDefaultCtor]
	public interface AgoraChatOptions {
		[Static]
		[Export ("optionsWithAppkey:")]
		AgoraChatOptions FromAppKey (string appKey);

		[Static]
		[Export ("optionsWithAppId:")]
		AgoraChatOptions FromAppId (string appId);

		[Export ("appkey")]
		string AppKey { get; }

		[Export ("appId")]
		string AppId { get; }

		[Export ("enableConsoleLog")]
		bool EnableConsoleLog { get; set; }

		[Export ("logLevel", ArgumentSemantic.Assign)]
		AgoraChatLogLevel LogLevel { get; set; }

		[Export ("isAutoLogin")]
		bool IsAutoLogin { get; set; }
	}

	// AgoraChatMessageBody — AgoraChatMessageBody.h. Abstract in practice: -init is marked
	// NS_UNAVAILABLE and every message carries one of the concrete subclasses.
	[BaseType (typeof (NSObject))]
	[DisableDefaultCtor]
	public interface AgoraChatMessageBody {
		[Export ("type")]
		AgoraChatMessageBodyType Type { get; }
	}

	// AgoraChatTextMessageBody — AgoraChatTextMessageBody.h. The only body type bound; the image,
	// video, voice, file, location, cmd, custom and combine bodies all follow the same shape.
	[BaseType (typeof (AgoraChatMessageBody))]
	[DisableDefaultCtor]
	public interface AgoraChatTextMessageBody {
		[Export ("initWithText:")]
		NativeHandle Constructor ([NullAllowed] string text);

		[Export ("text")]
		string Text { get; }
	}

	// AgoraChatMessage — AgoraChatMessage.h. The -initWithConversationID:body:ext: overload is the
	// one to use for sending: the SDK fills From from the logged-in user and To from the
	// conversation ID.
	[BaseType (typeof (NSObject))]
	[DisableDefaultCtor]
	public interface AgoraChatMessage {
		[Export ("initWithConversationID:body:ext:")]
		NativeHandle Constructor (string conversationId, AgoraChatMessageBody body, [NullAllowed] NSDictionary ext);

		[Export ("messageId")]
		string MessageId { get; set; }

		[Export ("conversationId")]
		string ConversationId { get; set; }

		[Export ("direction", ArgumentSemantic.Assign)]
		AgoraChatMessageDirection Direction { get; set; }

		[Export ("from")]
		string From { get; set; }

		[Export ("to")]
		string To { get; set; }

		// Milliseconds since the Unix epoch, server clock.
		[Export ("timestamp")]
		long Timestamp { get; set; }

		[Export ("chatType", ArgumentSemantic.Assign)]
		AgoraChatType ChatType { get; set; }

		[Export ("status", ArgumentSemantic.Assign)]
		AgoraChatMessageStatus Status { get; set; }

		[Export ("isRead")]
		bool IsRead { get; set; }

		[Export ("body", ArgumentSemantic.Strong)]
		AgoraChatMessageBody Body { get; set; }
	}

	// AgoraChatConversation — AgoraChatConversation.h. Read-only view: the ~25 message-management
	// methods on it (load, insert, delete, search, pin) stay unbound, since Net.Agora.Chat reads
	// history through the conversation list and the message delegate.
	[BaseType (typeof (NSObject))]
	[DisableDefaultCtor]
	public interface AgoraChatConversation {
		[Export ("conversationId")]
		string ConversationId { get; }

		[Export ("type")]
		AgoraChatConversationType Type { get; }

		[Export ("unreadMessagesCount")]
		int UnreadMessagesCount { get; }

		[Export ("messagesCount")]
		int MessagesCount { get; }

		[Export ("latestMessage", ArgumentSemantic.Strong)]
		AgoraChatMessage LatestMessage { get; }
	}

	// The generated C# interface for the protocol below, declared empty so that
	// AgoraChatClient.ChatManager can be typed with it and this file still compiles. The generator
	// replaces it with the real one; nothing here is emitted.
	//
	// AgoraChatClient hands the manager out as id<IAgoraChatManager> — the concrete type is
	// private to the SDK — so the interface is the only correct type for that property. Giving the
	// protocol a [BaseType] instead would generate a nameable class, but every method on it is a
	// stub that throws You_Should_Not_Call_base_In_This_Method: that class is for *implementing*
	// the protocol, and what is needed here is the generated wrapper around someone else's
	// instance, which is what the interface resolves to. (Verified the hard way — as a device-test
	// failure on the first run of the Chat suite.)
	public interface IAgoraChatManager {
	}

	// IAgoraChatManager — IAgoraChatManager.h. Every member is [Abstract]: the protocol declares
	// no @optional section, and required members are the ones generated onto the wrapper.
	[Protocol (Name = "IAgoraChatManager")]
	public interface AgoraChatManager {
		// aQueue may be null, which means "call me on the main thread".
		[Abstract]
		[Export ("addDelegate:delegateQueue:")]
		void AddDelegate ([NullAllowed] AgoraChatManagerDelegate aDelegate, [NullAllowed] DispatchQueue queue);

		[Abstract]
		[Export ("removeDelegate:")]
		void RemoveDelegate (AgoraChatManagerDelegate aDelegate);

		// Local only — reads the in-memory cache, falling back to the local database. It does not
		// hit the server, so it is empty until messages have been received or fetched.
		[Abstract]
		[Export ("getAllConversations")]
		[return: NullAllowed]
		AgoraChatConversation [] GetAllConversations ();

		[Abstract]
		[Export ("getConversationWithConvId:")]
		[return: NullAllowed]
		AgoraChatConversation GetConversation ([NullAllowed] string conversationId);

		// [Async] on a protocol member generates SendMessageAsync onto the interface's extension
		// methods, so it is reachable from the IAgoraChatManager the client hands out. Completes
		// rather than faults, like the client's methods above and for the same reason.
		[Abstract]
		[Export ("sendMessage:progress:completion:")]
		[Async (ResultTypeName = "AgoraChatMessageResult")]
		void SendMessage (AgoraChatMessage message, [NullAllowed] AgoraChatProgressHandler progress, [NullAllowed] AgoraChatMessageHandler completion);
	}

	// AgoraChatManagerDelegate — AgoraChatManagerDelegate.h. Every member is @optional. The
	// callbacks for read receipts, delivery receipts, recall, reactions, pinning and content
	// replacement stay unbound.
	[Protocol]
	[Model]
	[BaseType (typeof (NSObject))]
	public interface AgoraChatManagerDelegate {
		[Export ("messagesDidReceive:")]
		void MessagesDidReceive (AgoraChatMessage [] messages);

		[Export ("conversationListDidUpdate:")]
		void ConversationListDidUpdate (AgoraChatConversation [] conversations);

		[Export ("messageStatusDidChange:error:")]
		void MessageStatusDidChange (AgoraChatMessage message, [NullAllowed] AgoraChatError error);
	}

	// AgoraChatClientDelegate — AgoraChatClientDelegate.h. Every member is @optional. The
	// multi-device and offline-sync callbacks stay unbound; the deprecated
	// userAccountDidLoginFromOtherDevice pair is deliberately skipped in favour of nothing, since
	// its replacement carries a type this binding does not expose yet.
	[Protocol]
	[Model]
	[BaseType (typeof (NSObject))]
	public interface AgoraChatClientDelegate {
		[Export ("connectionStateDidChange:")]
		void ConnectionStateDidChange (AgoraChatConnectionState state);

		[Export ("userAccountDidRemoveFromServer")]
		void UserAccountDidRemoveFromServer ();

		[Export ("userAccountDidForcedToLogout:")]
		void UserAccountDidForcedToLogout ([NullAllowed] AgoraChatError error);

		// The parameter is an AgoraChatErrorCode; carried raw, as on AgoraChatError.Code.
		[Export ("tokenWillExpire:")]
		void TokenWillExpire (nint errorCode);

		[Export ("tokenDidExpire:")]
		void TokenDidExpire (nint errorCode);
	}

	// AgoraChatClient — AgoraChatClient.h. A singleton: -init, -copy and -mutableCopy are all
	// marked unavailable, hence [DisableDefaultCtor].
	//
	// The eight other managers it exposes (contact, group, thread, room, push, userInfo, presence,
	// statistics) are not bound — only ChatManager, which is what messaging needs.
	[BaseType (typeof (NSObject))]
	[DisableDefaultCtor]
	public interface AgoraChatClient {
		[Static]
		[Export ("sharedClient")]
		AgoraChatClient SharedClient { get; }

		[Export ("version")]
		string Version { get; }

		[NullAllowed]
		[Export ("currentUsername")]
		string CurrentUsername { get; }

		[Export ("options", ArgumentSemantic.Strong)]
		AgoraChatOptions Options { get; }

		[NullAllowed]
		[Export ("chatManager", ArgumentSemantic.Strong)]
		IAgoraChatManager ChatManager { get; }

		[Export ("isLoggedIn")]
		bool IsLoggedIn { get; }

		[Export ("isConnected")]
		bool IsConnected { get; }

		// Synchronous, and returns nil on success — the SDK's convention for its non-block calls.
		[Export ("initializeSDKWithOptions:")]
		[return: NullAllowed]
		AgoraChatError InitializeSdk (AgoraChatOptions options);

		[Export ("addDelegate:delegateQueue:")]
		void AddDelegate (AgoraChatClientDelegate aDelegate, [NullAllowed] DispatchQueue queue);

		[Export ("removeDelegate:")]
		void RemoveDelegate (NSObject aDelegate);

		// The completion methods carry [Async] so every operation also has an awaitable form,
		// like Signaling's. The Task completes rather than faults on a Chat error — necessarily,
		// not just by Signaling's convention: AgoraChatError is not an NSError, so the generator
		// has no error to fault with and hands the whole callback back as the result. A null
		// error means success everywhere. ResultTypeName only where the handler carries more
		// than one value: for the single-parameter AgoraChatCompletionHandler the generator
		// returns Task<AgoraChatError> directly and would emit the named class as an orphan —
		// verified against the generated code — so Logout/RenewToken name none.

		[Export ("loginWithUsername:token:completion:")]
		[Async (ResultTypeName = "AgoraChatLoginResult")]
		void Login (string username, string token, [NullAllowed] AgoraChatLoginHandler completion);

		// unbindDeviceToken only matters to an app that registered for APNs; pass false otherwise.
		[Export ("logout:completion:")]
		[Async]
		void Logout (bool unbindDeviceToken, [NullAllowed] AgoraChatCompletionHandler completion);

		[Export ("renewToken:completion:")]
		[Async]
		void RenewToken (string newToken, [NullAllowed] AgoraChatCompletionHandler completion);
	}
}
